#!/bin/sh
# kitty 图形协议 / 光标控制 对齐诊断
#
# 两件事分开测，互不牵连：
#   1  CSI s / CSI u  完全不涉及图片，纯文本测保存与恢复光标
#   2  占位符行定位    完全不涉及光标技巧，只用 \r 和绝对列定位
#
# 在真 Ghostty 和待测终端上各跑一次对照。

printf "终端: ${TERM_PROGRAM:-?} ${TERM_PROGRAM_VERSION:-?}  TERM=${TERM:-?}\n\n"

printf "1  CSI s / CSI u（不涉及图片）\n"
printf "   下面一行应当只看到 [OK]，位置在行首：\n"
   # 行首保存 → 写一串占位文字 → 恢复 → 覆盖成 [OK]
printf '   \033[s........................\033[u   [OK]\n'
printf "   若看到那串点、或 [OK] 跑到别处，这个终端没有正确实现 SCOSC/SCORC。\n\n"

printf "2  一行高的图，标签在同一行（最小例）\n"
printf '\033_Gq=2,i=10551297,a=T,U=1,f=32,t=d,s=64,v=35,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=0;\033\\'
printf '\r\033[38;2;161;0;1m􎻮̅̅̅􎻮􎻮􎻮\033[0m\033[8G← 方块应当整个落在本行\n'
printf "\n"
printf "3  两行高的图，标签在对应行\n"
printf '\033_Gq=2,i=10616834,a=T,U=1,f=32,t=d,s=64,v=70,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=1;\033\\\033_Gq=2,m=0;\033\\'
printf '\r\033[38;2;162;0;2m􎻮̅̅̅􎻮􎻮􎻮\033[0m\033[8G← 上边应与本行齐平\n'
printf '\r\033[38;2;162;0;2m􎻮̍̅̅􎻮􎻮􎻮\033[0m\033[8G← 下边应与本行齐平\n'
printf "\n"
printf "2 里方块和标签不在同一行 → 占位符的行定位有问题（与光标无关）。\n"
